from fastapi import FastAPI
from pydantic import BaseModel
from fastapi.middleware.cors import CORSMiddleware
import joblib
import pandas as pd

app = FastAPI()

# Allow React to communicate with this API
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"], # Update with your React app's local URL in production
    allow_methods=["*"],
    allow_headers=["*"],
)

# Load the model artifact generated by train_model.py
artifact = joblib.load('crop_yield_rf_model.joblib')
model = artifact['model']
model_features = artifact['features']

# Define the expected JSON payload structure from React
class CropData(BaseModel):
    tavg_c: float
    extreme_heat_days: int
    precip_anomaly_pct: float
    mean_dsci: float
    aws_100cm_mm: float
    crop_SORGHUM: bool = False
    crop_SOYBEANS: bool = False
    crop_WHEAT: bool = False

@app.post("/predict")
def predict_yield(data: CropData):
    # Convert incoming JSON data into a DataFrame matching the model's exact feature layout
    input_data = data.model_dump()
    input_df = pd.DataFrame([input_data])[model_features]
    
    # Generate prediction
    prediction = model.predict(input_df)[0]
    
    return {"predicted_yield_anomaly_pct": round(prediction, 2)}